import type { PolymorphicRef } from "@types";
import type { VerticalTabBarMainProps } from "../vertical-tab-bar.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

export const VerticalTabBarMain = forwardRef(function VerticalTabBarMain<
  C extends React.ElementType = "div",
>({ className, children, as, ...props }: VerticalTabBarMainProps<C>, ref: PolymorphicRef) {
  const classes = clsx(VerticalTabBarClasses.main, className);
  const Component = as || "div";

  return (
    <Component ref={ref} className={classes} {...props}>
      {children}
    </Component>
  );
});

VerticalTabBarMain.displayName = "VerticalTabBar.Main";
